mapper.select:
SELECT id, name, description, category_id, poster_url, venue, status, create_time, update_time
FROM `show`
WHERE id = #{id}

SELECT s.id, s.name, s.description, s.category_id, s.poster_url, s.venue,
       s.status, s.create_time, s.update_time, c.name AS category_name
FROM `show` s
LEFT JOIN category c ON c.id = s.category_id

    AND s.status = #{status}
    AND s.name LIKE CONCAT(#{name}, '%')
    AND s.category_id = #{categoryId}
    AND s.venue LIKE CONCAT(#{venue}, '%')

ORDER BY s.create_time DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM `show` s

    AND s.status = #{status}
    AND s.name LIKE CONCAT(#{name}, '%')
    AND s.category_id = #{categoryId}
    AND s.venue LIKE CONCAT(#{venue}, '%')
